{"file_path":"src/election.js","content":"/**
 * Counts an instant-runoff election: repeatedly tallies each ballot for its
 * most-preferred continuing candidate, declares a winner once someone holds
 * a strict majority of the active votes, and otherwise eliminates the
 * candidate with the fewest votes and counts another round.
 */

/**
 * @param {string[]} candidates declared candidate names, in declaration order
 * @param {{count: number, names: string[]}[]} ballots
 * @returns {{rounds: {votes: Map<string, number>, exhausted: number, eliminated: string | null}[], winner: string | null}}
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const pick = ballot.names.find((name) => continuing.has(name))
      if (pick === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(pick, votes.get(pick) + ballot.count)
      }
    }

    history.push(votes)

    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const roundWinner = [...votes].find(([, count]) => count * 2 > activeTotal)
    if (roundWinner) {
      winner = roundWinner[0]
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const eliminated = pickElimination(votes, history)
    continuing.delete(eliminated)
    rounds.push({ votes, exhausted, eliminated })
  }

  return { rounds, winner }
}

/**
 * Chooses which of the lowest-scoring candidates in the current round to
 * eliminate, breaking ties by earlier rounds and finally by name.
 */
function pickElimination(votes, history) {
  const minVotes = Math.min(...votes.values())
  let tied = [...votes.keys()].filter((name) => votes.get(name) === minVotes)

  for (let round = 0; round < history.length && tied.length > 1; round++) {
    const roundVotes = history[round]
    const min = Math.min(...tied.map((name) => roundVotes.get(name)))
    tied = tied.filter((name) => roundVotes.get(name) === min)
  }

  if (tied.length === 1) return tied[0]
  return tied.sort().at(-1)
}
"}

