{"file_path":"src/format.js","content":"/**
 * Renders an election result as the `rounds` or `tally` output formats.
 */

/**
 * @param {{rounds: {votes: Map<string, number>, exhausted: number, eliminated: string | null}[], winner: string | null}} result
 */
export function formatRounds(result) {
  const lines = []
  result.rounds.forEach((round, index) => {
    const entries = [...round.votes].sort(([nameA, votesA], [nameB, votesB]) => {
      if (votesA !== votesB) return votesB - votesA
      return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
    })
    const scores = entries.map(([name, votes]) => `${name}=${votes}`).join(' ')
    lines.push(`round ${index + 1}: ${scores} exhausted=${round.exhausted}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(result.winner === null ? 'no winner' : `winner ${result.winner}`)
  return lines.map((line) => `${line}\n`).join('')
}

/**
 * @param {{rounds: unknown[], winner: string | null}} result
 */
export function formatTally(result) {
  const winnerLine = result.winner === null ? 'no winner' : `winner ${result.winner}`
  return `rounds ${result.rounds.length}\n${winnerLine}\n`
}
"}

